// --- boot -----------------------------------------------------------------

/* Everything the page drew itself, redrawn in the language just chosen. The
 * static markup is the i18n module's own job; this is the rest. */
function retranslate() {
  renderChrome();
  if (!state.catalogue) return;
  renderTimelineStrip();
  renderHeaderHint();
  renderPeriodBar();
  renderPoolNote();
  renderOriginCard();
  renderPrefs();
  buildDayHeader();
  buildFacets();
  syncFacetChrome();
  rebuild();
  layoutOverlay();
}

// --- the year, and which festival the page is zoomed in on -----------------

/** Today on the festival's own calendar — the pinned clock in a case. */
function todayISO() {
  return new Date().toISOString().slice(0, 10);
}

function renderTimelineStrip() {
  const monthFmt = (options) => new Intl.DateTimeFormat(currentIntlLocale(), { timeZone: "UTC", ...options });
  renderTimeline($("timeline"), {
    registry: state.registry,
    span: timelineSpan(todayISO()),
    todayISO: todayISO(),
    focusKey: state.focus ? state.focus.key : null,
    period: state.period,
    label: (festival, edition) => ({
      name: wordmarkOf(festival).join(" "),
      tip: `${festivalName(festival)} · ${dates({ day: "numeric", month: "short", year: "numeric" }).formatRange(
        dateOf(edition.firstDate),
        dateOf(edition.lastDate)
      )}`,
    }),
    // A month is its short name; January also says which year has begun.
  state.search.genres.clear();
  state.search.venues.clear();

  $("planPanel").hidden = false;
  $("boardDrawer").hidden = false;
  renderChrome();
  renderTimelineStrip();
  renderHeaderHint();
  renderPeriodBar();
  renderPoolNote();
  renderOriginCard();
  renderPrefs();
/* --- the reader's own two controls ---------------------------------------- */

/* Language and theme sit at the end of the header, after the festival's dates:
   they belong to the reader rather than to the festival, so they read as the
   last thing in the bar rather than as part of its identity. */
.chrome-prefs {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-inline-start: 10px;
}
  "nav.primaryLabel": {
    maxWidthPx: null,
    unrendered: "the site navigation's accessible name",
    en: "Primary",
    he: "ראשי",
    ru: "Основная",
    ja: "メイン",
  },
  "header.run": {
    maxWidthPx: 375,
    sample: { city: "Jerusalem", range: "18–22 Oct 2026" },
    en: "{city} · {range}",
    he: "{city} · {range}",
    ru: "{city} · {range}",
    ja: "{city} · {range}",
  },
