"use strict";
const { jerusalemReady, jerusalemStarred, settle } = require("../../shared/case-helpers");

module.exports = {
  description: "the bed link: Booking.com's Hebrew edition, Jerusalem, shekels, the window's own nights",
  page: "/planNG/?festival=jerusalem-comedy",
  viewport: "desktop",
  localStorage: jerusalemStarred(),
  async verify(page, { origin, assert }) {
    await page.goto(`${origin}/planNG/?festival=jerusalem-comedy`, { waitUntil: "load" });
    await jerusalemReady(page);

    // Asserted as a URL, never followed — the partner is a real booking site.
    const href = await page.locator(".trip-link").first().getAttribute("href");
    const url = new URL(href);
    assert.equal(url.host, "www.booking.com");
    assert.equal(url.pathname, "/searchresults.he.html", "the Hebrew edition lives at its own path");
    assert.equal(url.searchParams.get("ss"), "Jerusalem");
    assert.equal(url.searchParams.get("selected_currency"), "ILS");

    // The nights are the date window's, not the festival's — which opens on
    // the run and a day either side (23.2) — so narrow the window and the link
    // has to follow it.
    assert.equal(url.searchParams.get("checkin"), "2026-10-17");
    assert.equal(url.searchParams.get("checkout"), "2026-10-23");
    await page.locator(".sch-dateedge--start").focus();
    await page.keyboard.press("ArrowRight");
    await settle(page);
    const moved = new URL(await page.locator(".trip-link").first().getAttribute("href"));
    assert.equal(moved.searchParams.get("checkin"), "2026-10-18");

    // A partner link is disclosed as one.
    assert.equal(await page.locator(".trip-link").first().getAttribute("rel"), "sponsored noopener noreferrer");
  },
};
"use strict";
const { jerusalemReady, jerusalemStarred } = require("../../shared/case-helpers");

module.exports = {
  description: "getting here: the paid airport transfer, and the train offered beside it",
  page: "/planNG/?festival=jerusalem-comedy",
  viewport: "desktop",
  localStorage: jerusalemStarred(),
  async verify(page, { origin, assert }) {
    await page.goto(`${origin}/planNG/?festival=jerusalem-comedy`, { waitUntil: "load" });
    await jerusalemReady(page);

    const links = page.locator(".trip-link");
    const hrefs = await links.evaluateAll((els) => els.map((e) => e.getAttribute("href")));
    const partners = await links.evaluateAll((els) =>
      els.map((e) => e.querySelector(".trip-link-partner").textContent)
    );

    assert.deepEqual(partners.slice(1), ["Kiwitaxi", "Israel Railways"]);
    assert.equal(hrefs[1], "https://kiwitaxi.com/en/israel/ben-gurion-airport");
    // Untagged, and it must stay that way: Israel Railways runs no referral
    // programme, and the train is offered anyway because it is usually the
    // right answer from the airport.
    assert.equal(hrefs[2], "https://www.rail.co.il/en");
  },
};
"use strict";
const { jerusalemReady, plannerReady } = require("../../shared/case-helpers");

const offered = (page) =>
  page.$$eval("#tripLinksRow .trip-link-text", (els) => els.map((e) => e.dataset.i18nSlot));

/* Each answer to "where are you coming from?", and the trip links it leaves:
 * none from the festival's own city, a bed and a train from elsewhere in the
 * country, the airport too from abroad. Asked once: the next festival chosen
 * does not ask again. */
module.exports = {
  description: "the answer decides the trip links, and is asked once across festivals",
  page: "/planNG/?festival=jerusalem-comedy",
  viewport: "desktop",
  async verify(page, { origin, assert }) {
    await page.goto(`${origin}/planNG/?festival=jerusalem-comedy`, { waitUntil: "load" });
    await jerusalemReady(page);
    assert.equal(await page.isVisible("#originCard"), true, "a first visit is asked");

    await page.click('#originCard [data-origin="city"]');
    assert.equal(await page.isVisible("#originCard"), false, "an answer puts the question away");
    assert.deepEqual(await offered(page), [], "the festival's own city: nothing to book");
    assert.equal(await page.isVisible("#tripLinksRow .trip-local"), true, "and the page says why");

    await page.click('#originLine [data-origin="change"]');
    await page.click('#originCard [data-origin="country"]');
    assert.deepEqual(await offered(page), ["trip.stay", "trip.rail"], "elsewhere in the country: a bed and a train");

    await page.click('#originLine [data-origin="change"]');
    await page.selectOption("#originCountry", "FR");
    assert.deepEqual(
      await offered(page),
      ["trip.stay", "trip.transfers", "trip.rail"],
      "abroad: a bed, the airport and the train"
    );
    assert.deepEqual(
      await page.evaluate(() => JSON.parse(localStorage.getItem("planNG.origin"))),
      { kind: "abroad", country: "FR" },
      "the answer is stored"
    );

    await page.click('.tl-item[data-festival="haifa-iff"]');
    await plannerReady(page, "haifa-iff");
    assert.equal(await page.isVisible("#originCard"), false, "the next festival does not ask again");
    assert.deepEqual(
      await offered(page),
      ["trip.stay", "trip.transfers", "trip.rail"],
      "and judges the same answer for its own city"
    );
  },
};
