/* --- the trip links ------------------------------------------------------ */

/* The Fringe planner grows these as pop-up nags on the schedule's dead zones.
   Five nights leave no dead zone worth the trick, so they are one quiet row
   under the board — same question, same disclosure, less machinery. */
.trip-links {
  margin: 14px 0 0;
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: rgba(184, 134, 43, 0.05);
}
.trip-links-title {
  margin: 0 0 8px;
  font-family: var(--display);
  font-weight: 700;
  font-size: 0.85rem;
}
.trip-links-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.trip-link {
  display: inline-flex;
  align-items: baseline;
  gap: 7px;
  padding: 7px 12px;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: var(--paper);
  text-decoration: none;
  color: var(--ink);
  font-size: 0.82rem;
  font-weight: 600;
}
.trip-link:hover {
  border-color: var(--violet);
  color: var(--violet-dark);
}
.trip-link-partner {
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--muted);
}

/* --- the reader's own two controls ---------------------------------------- */

/* Language and theme sit at the end of the header: they belong to the reader
   rather than to the site, so they read as the last thing in the bar rather
   than as part of its identity. */
.chrome-prefs {
}
.origin-answers {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.origin-abroad {
  gap: 6px;
}
.origin-select {
  max-width: 190px;
}
.origin-skip,
.origin-change {
  margin-top: 8px;
  padding: 0;
  border: 0;
  background: none;
  font: inherit;
  font-size: 0.8rem;
  color: var(--violet-dark);
  text-decoration: underline;
  cursor: pointer;
}
.origin-change {
  margin-top: 0;
}
.origin-status {
  margin: 6px 0 0;
  font-size: 0.8rem;
  color: var(--muted);
}
.origin-status:empty {
  display: none;
}
.origin-line {
  margin: 0 0 6px;
  font-size: 0.82rem;
  color: var(--muted);
}
.trip-local {
  margin: 0;
  font-size: 0.86rem;
}

/* --- a list too long to draw --------------------------------------------- */

.browse-more {
  padding: 8px 0 4px;
  text-align: center;
  font-size: 0.86rem;

